attributes.cssVariables:
:root {
  /* ServiceDesk — the quiet palette.
     Warm neutrals, not cool: this surface is stared at for a whole shift, and a
     cool ramp both reads clinical and fights the amber/red that carry meaning.
     One accent, used for selection / focus / primary action only — never
     decoration, because green and red are already spoken for by SLA state. */
  --background: #faf9f8;
  --foreground: #1c1b19;
  --card: #ffffff;
  --card-foreground: #1c1b19;
  --popover: #ffffff;
  --popover-foreground: #1c1b19;
  --primary: #5a53c9;
  --primary-foreground: #ffffff;
  --secondary: #f3f2f0;
  --secondary-foreground: #1c1b19;
  --muted: #f3f2f0;
  --muted-foreground: #6b6863;
  --accent: #efeefb;
  --accent-foreground: #1c1b19;
  --destructive: #a8291d;
  --destructive-foreground: #ffffff;
  /* Deliberately faint. "Structure should be felt not seen" — the previous
     value made every row read as a competing rectangle. */
  --border: #e7e5e1;
  --input: #ffffff;
  --ring: #5a53c9;
  --radius: 0.375rem;
  --font-sans: system-ui, -apple-system, 'Segoe UI', sans-serif;
  --font-serif: ui-serif, Georgia, serif;
  --font-mono: ui-monospace, 'SF Mono', Menlo, Consolas, monospace;
  --font-heading: system-ui, -apple-system, 'Segoe UI', sans-serif;

  /* The catalog popover's `edit` kind paints a sticky-note yellow as a
     semantic "unsaved" signal, and it exposes these two vars so a theme can
     say otherwise. Here nothing is ever unsaved: every choice in a link
     picker commits the moment it is made, so a "you have not saved this"
     colour would be telling the reader something untrue. Neutral card
     surface instead — the popover keeps its own shadow, radius and
     positioning. */
  --bx-popover-edit-bg: #ffffff;
  --bx-popover-edit-border: #e7e5e1;
}
